{"path": "api/tz_test.go", "old": "", "new": "package api_test

import (
	"net/http"
	"testing"
)

// A weekly reminder with a zone that doesn't exist must be refused when it
// is created, not stored: listing it later dereferences the nil zone.
func TestCreateRejectsUnknownZone(t *testing.T) {
	c := newClient(t)
	body := `{"text":"standup","every":"on mon at 09:00","tz":"Mars/Olympus"}`
	if code := c.do("tok-ana", http.MethodPost, "/v1/reminders", body, nil); code != http.StatusBadRequest {
		t.Fatalf("create with unknown zone: status %d, want 400", code)
	}
	if code := c.do("tok-ana", http.MethodGet, "/v1/reminders", "", nil); code != http.StatusOK {
		t.Fatalf("list: status %d", code)
	}
}
"}

